def cobs_encode(data):
    out = bytearray()
    out.append(0)
    block = 0
    code = 1
    for byte in data:
        if byte == 0:
            out[block] = code
            block = len(out)
            out.append(0)
            code = 1
        else:
            out.append(byte)
            code += 1
        if code == 255:
            out[block] = code
            block = len(out)
            out.append(0)
            code = 1
    out[block] = code
    return bytes(out)


def cobs_decode(data):
    out = bytearray()
    i = 0
    n = len(data)
    if 0 in data:
        raise ValueError("zero byte in encoded input")
    while i < n:
        code = data[i]
        i += 1
        end = i + code - 1
        if end > n:
            raise ValueError("encoded group runs past end of input")
        out += data[i:end]
        i = end
        if code < 255:
            if i < n:
                out.append(0)
        elif i == n:
            raise ValueError("trailing 255 code byte with no following group")
    return bytes(out)
